CREATE TABLE IF NOT EXISTS action_idempotency(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,scope VARCHAR(60) NOT NULL,request_key VARCHAR(100) NOT NULL,request_hash CHAR(64) NOT NULL,result_json LONGTEXT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY identity_key(user_id,scope,request_key),FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS registration_drafts(user_id INT PRIMARY KEY,step INT NOT NULL DEFAULT 2,payload LONGTEXT NOT NULL,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS registration_events(companion_id INT PRIMARY KEY,source VARCHAR(20) NOT NULL,counted TINYINT NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(companion_id) REFERENCES companions(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS uploaded_media(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,path VARCHAR(255) NOT NULL UNIQUE,mime VARCHAR(80) NOT NULL,private TINYINT NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS serial_aliases(alias VARCHAR(100) PRIMARY KEY,companion_id INT NOT NULL,reason VARCHAR(255) NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(companion_id) REFERENCES companions(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS lost_cases(id INT AUTO_INCREMENT PRIMARY KEY,companion_id INT NOT NULL,state VARCHAR(20) NOT NULL,activated_by INT NOT NULL,activated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,resolved_by INT NULL,resolved_at DATETIME NULL,reason TEXT NULL,INDEX companion_state(companion_id,state),FOREIGN KEY(companion_id) REFERENCES companions(id),FOREIGN KEY(activated_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS qr_scan_events(id INT AUTO_INCREMENT PRIMARY KEY,public_id CHAR(48) NOT NULL UNIQUE,companion_id INT NOT NULL,lost_case_id INT NULL,kind VARCHAR(20) NOT NULL DEFAULT 'tag',nonce_hash CHAR(64) NOT NULL UNIQUE,visitor_hash CHAR(64) NOT NULL,received_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,location_status VARCHAR(30) NOT NULL DEFAULT 'not_requested',location_cipher LONGTEXT NULL,capability_hash CHAR(64) NOT NULL,capability_expires DATETIME NOT NULL,consent_version VARCHAR(30) NULL,consent_at DATETIME NULL,location_expires DATETIME NULL,INDEX companion_time(companion_id,received_at),FOREIGN KEY(companion_id) REFERENCES companions(id),FOREIGN KEY(lost_case_id) REFERENCES lost_cases(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS qr_scan_event_entries(id BIGINT AUTO_INCREMENT PRIMARY KEY,event_id INT NOT NULL,type VARCHAR(40) NOT NULL,server_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY event_type(event_id,type),FOREIGN KEY(event_id) REFERENCES qr_scan_events(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS notification_outbox(id BIGINT AUTO_INCREMENT PRIMARY KEY,notification_id INT NOT NULL,channel VARCHAR(20) NOT NULL,status VARCHAR(20) NOT NULL,attempts INT NOT NULL DEFAULT 0,next_attempt_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,locked_until DATETIME NULL,last_error VARCHAR(80) NULL,accepted_at DATETIME NULL,UNIQUE KEY notification_channel(notification_id,channel),FOREIGN KEY(notification_id) REFERENCES notifications(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS rate_limits(bucket_key CHAR(64) NOT NULL,bucket BIGINT NOT NULL,hits INT NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(bucket_key,bucket)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS quotes(id CHAR(48) PRIMARY KEY,user_id INT NULL,request_hash CHAR(64) NOT NULL,payload LONGTEXT NOT NULL,expires_at DATETIME NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS crm_contacts(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NULL UNIQUE,name VARCHAR(150) NOT NULL,email VARCHAR(190) NULL,phone VARCHAR(40) NULL,kind VARCHAR(20) NOT NULL DEFAULT 'prospect',status VARCHAR(20) NOT NULL DEFAULT 'active',companion_id INT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(companion_id) REFERENCES companions(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS crm_activity(id INT AUTO_INCREMENT PRIMARY KEY,contact_id INT NOT NULL,actor_id INT NOT NULL,type VARCHAR(20) NOT NULL,channel VARCHAR(20) NULL,body TEXT NOT NULL,due_at DATETIME NULL,assigned_to INT NULL,status VARCHAR(20) NOT NULL DEFAULT 'open',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,completed_at DATETIME NULL,FOREIGN KEY(contact_id) REFERENCES crm_contacts(id),FOREIGN KEY(actor_id) REFERENCES users(id),FOREIGN KEY(assigned_to) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS content_versions(id INT AUTO_INCREMENT PRIMARY KEY,slug VARCHAR(120) NOT NULL,title_fr VARCHAR(200) NOT NULL,title_ar VARCHAR(200) NOT NULL,body_fr LONGTEXT NOT NULL,body_ar LONGTEXT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'draft',author_id INT NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,published_at DATETIME NULL,INDEX content_lookup(slug,status,id),FOREIGN KEY(author_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS contact_requests(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,email VARCHAR(190) NOT NULL,message TEXT NOT NULL,language CHAR(2) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'new',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
